  "implementation": "def solve(case):
    passing = case["passing"]
    failing = case["failing"]
    required = case.get("required_difference", [])
    unresolved = case.get("unresolved_difference", [])
    if not isinstance(passing, list) or not isinstance(failing, list):
        raise ValueError("passing and failing must be lists")
    # compute difference D (ordered by failing)
    D = []
    seen = set(passing)
    for item in failing:
        if item not in seen:
            D.append(item)
            seen.add(item)
    # validate feasibility
    if not set(required).issubset(set(D)):
        raise ValueError("required_difference not subset of difference")
    # counting oracle calls
    call_count = 0
    def oracle(S):
        nonlocal call_count
        call_count += 1
        # unresolved -> UNRESOLVED
        for x in S:
            if x in unresolved:
                return -1
        # required check
        for r in required:
            if r not in S:
                return 0
        return 1
    # check empty set
    if oracle([]) == 1:
        return {"isolated_difference": [], "tests": call_count}
    if not D:
        if not required:
            return {"isolated_difference": [], "tests": 0}
        else:
            raise ValueError("no difference but required non-empty")
    # full difference must fail
    if oracle(D) != 1:
        raise ValueError("full difference does not cause failure")
    # ddmin helpers
    def partition(lst, n):
        k, m = divmod(len(lst), n)
        out = []
        start = 0
        for i in range(n):
            end = start + k + (1 if i < m else 0)
            out.append(lst[start:end])
            start = end
        return out
    def ddmin(cs, n):
        if len(cs) == 1:
            return cs
        subsets = partition(cs, n)
        # test each subset
        for sub in subsets:
            res = oracle(sub)
            if res == 1:
                return ddmin(sub, 2)
        # test complements
        for sub in subsets:
            comp = [x for x in cs if x not in sub]
            res = oracle(comp)
            if res == 1:
                return ddmin(comp, max(n - 1, 2))
        # increase granularity
        if n < len(cs):
            return ddmin(cs, min(2 * n, len(cs)))
        else:
            return cs
    isolated = ddmin(D, 2)
    return {"isolated_difference": isolated, "tests": call_count}
